package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import org.json.*;
import org.junit.Test;

public final class ProjectCommandSpecTest {
    private JSONObject command()throws Exception{return new JSONObject().put("executable","node").put("argv",new JSONArray().put("-e").put("console.log(process.argv[1])").put("a b; $(not-a-shell) 😀"));}
    @Test public void exactArgvHasNoShellSplittingAndPayloadRoundTrips()throws Exception{JSONObject p=ProjectCommandSpec.normalize(command());assertEquals("a b; $(not-a-shell) 😀",p.getJSONArray("argv").getString(2));assertEquals(".",p.getString("workingDirectory"));assertEquals("pipes",p.getString("terminalMode"));assertEquals(ProjectSources.canonical(p),ProjectSources.canonical(ProjectCommandSpec.fromPayload(p)));}
    @Test public void cwdTraversalAbsoluteAndInvalidToolAreRejected()throws Exception{for(String cwd:new String[]{"../outside","/data/data/other","src/../other","src\\a"})assertThrows(Exception.class,()->ProjectCommandSpec.normalize(command().put("cwd",cwd)));assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.normalize(command().put("executable","/bin/sh")));assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.normalize(command().put("executable","node -e")));}
    @Test public void ordinaryReviewedEnvironmentIsNotAHostEnvironmentOverride()throws Exception{JSONObject p=ProjectCommandSpec.normalize(command().put("cwd","src/scripts").put("env",new JSONObject().put("APP_DELTA","5.00").put("PW_USER_LABEL","a b").put("NODE_ENV","test")));assertEquals("src/scripts",p.getString("workingDirectory"));assertEquals("5.00",p.getJSONObject("environment").getString("APP_DELTA"));for(String key:new String[]{"PATH","HOME","TMPDIR","LD_PRELOAD","NODE_OPTIONS","PYTHONPATH","ENV","BASH_ENV","SHELLOPTS","PROOT_LOADER","POCKETWORLD_ENVIRONMENT_IDENTITY","APP_API_TOKEN","APP_PASSWORD"})assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.normalize(command().put("env",new JSONObject().put(key,"must-not-be-logged"))));}
    @Test public void ptyRequiresExplicitSameRunServiceAndBoundedInputs()throws Exception{assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.normalize(command().put("terminal","pty")));JSONObject p=ProjectCommandSpec.normalize(command().put("terminal","pty").put("runMode","owned_service").put("columns",100).put("rows",30).put("inputByteLimit",1234));assertTrue(p.getBoolean("interactiveInputExplicitlyIncluded"));assertTrue(p.getBoolean("terminalOutputMerged"));assertEquals(1234,p.getInt("inputByteLimit"));assertEquals(ProjectSources.canonical(p),ProjectSources.canonical(ProjectCommandSpec.fromPayload(p)));}
    @Test public void invalidIntegersArgumentsAndSecretLikeEnvironmentDoNotEchoValues()throws Exception{assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.normalize(command().put("timeoutMillis",1.5)));assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.normalize(command().put("timeoutMillis",300001)));assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.normalize(command().put("columns",80)));assertThrows(IllegalArgumentException.class,()->ProjectCommandSpec.normalize(command().put("argv",new JSONArray().put("bad\0value"))));try{ProjectCommandSpec.normalize(command().put("env",new JSONObject().put("APP_SECRET","sensitive-canary")));fail();}catch(IllegalArgumentException expected){assertFalse(expected.getMessage().contains("sensitive-canary"));}}
    @Test public void tamperedNativeInteractiveConsentIsNotNormalizedIntoApproval()throws Exception{JSONObject p=ProjectCommandSpec.normalize(command().put("terminal","pty").put("runMode","owned_service"));p.put("interactiveInputExplicitlyIncluded",false);assertThrows(SecurityException.class,()->ProjectCommandSpec.fromPayload(p));}
}
